CREATE FUNCTION [dbo].[VISITORS_KOL] (@DT1 bigint, @DT2 bigint, @visitor nvarchar(40)) RETURNS Table AS RETURN (
WITH VisitorCounts AS (
    SELECT NUMBER, TAG, COUNT(*) AS VCount
    FROM dbo.VISITOR_DTLO
    GROUP BY NUMBER, TAG
)
SELECT     dbo.VISITOR_DTLO.CUST_NO, SUM(dbo.VISITOR_DTLO.mabpur) AS mabpur, SUM(JAMFACTVISIT.MABL_K / ISNULL(vc.VCount, 1)) AS MABL_K, SUM(JAMFACTVISIT.MEGHk / ISNULL(vc.VCount, 1)) AS MEGHk,  SUM(JAMFACTVISIT.MEGH_MAR / ISNULL(vc.VCount, 1)) AS MEGH_MAR, SUM(JAMFACTVISIT.N_MOIN / ISNULL(vc.VCount, 1)) AS TAKHF, SUM(JAMFACTVISIT.IMBAA / ISNULL(vc.VCount, 1)) AS MBAA, SUM(JAMFACTVISIT.MABMAR / ISNULL(vc.VCount, 1))  AS MABMAR, SUM(JAMFACTVISIT.GHABEL / ISNULL(vc.VCount, 1)) AS GHABEL, dbo.CUST_HESAB.NAME, dbo.CUST_HESAB.ADDRESS, dbo.CUST_HESAB.TEL, dbo.CUST_HESAB.TOZIH,  dbo.CUST_HESAB.MOBILE, COUNT(JAMFACTVISIT.NUMBER) / ISNULL(MAX(vc.VCount), 1) AS tedad FROM         dbo.CUST_HESAB INNER JOIN  dbo.VISITOR_DTLO ON dbo.CUST_HESAB.hes = dbo.VISITOR_DTLO.CUST_NO INNER JOIN  dbo.JAMFACTVISIT(@DT1, @DT2) JAMFACTVISIT ON dbo.VISITOR_DTLO.NUMBER = JAMFACTVISIT.NUMBER AND dbo.VISITOR_DTLO.TAG = JAMFACTVISIT.TAG LEFT JOIN VisitorCounts AS vc ON dbo.VISITOR_DTLO.NUMBER = vc.NUMBER AND dbo.VISITOR_DTLO.TAG = vc.TAG  GROUP BY dbo.VISITOR_DTLO.CUST_NO, dbo.CUST_HESAB.NAME, dbo.CUST_HESAB.ADDRESS, dbo.CUST_HESAB.TEL, dbo.CUST_HESAB.TOZIH,  dbo.CUST_HESAB.MOBILE HAVING      (dbo.VISITOR_DTLO.CUST_NO LIKE @visitor) )
